/// Closed body outline in the source 240 viewBox. First point is the top; winding is clockwise.
pub fn body_points(shape: BodyShape) -> &'static [[f64; 2]; 72] {
    match shape {
        BodyShape::Circle => &BODY_CIRCLE,
        BodyShape::Squircle => &BODY_SQUIRCLE,
        BodyShape::Cloud => &BODY_CLOUD,
        BodyShape::Bubble => &BODY_BUBBLE,
        BodyShape::Puddle => &BODY_PUDDLE,
        BodyShape::Burst => &BODY_BURST,
        BodyShape::Pebble => &BODY_PEBBLE,
        BodyShape::Bean => &BODY_BEAN,
    }
}

/// Left eye, then right eye, placed with the source `placeEye` rules.
pub fn face_points(face: FaceName) -> &'static [[[f64; 2]; 48]; 2] {
    match face {
        FaceName::Neutral => &FACE_NEUTRAL,
        FaceName::Dots => &FACE_DOTS,
        FaceName::Wide => &FACE_WIDE,
        FaceName::Tiny => &FACE_TINY,
        FaceName::Lines => &FACE_LINES,
        FaceName::Focus => &FACE_FOCUS,
        FaceName::Worry => &FACE_WORRY,
        FaceName::Smirk => &FACE_SMIRK,
        FaceName::Happy => &FACE_HAPPY,
        FaceName::Content => &FACE_CONTENT,
        FaceName::Sleepy => &FACE_SLEEPY,
        FaceName::Dizzy => &FACE_DIZZY,
        FaceName::Sparkle => &FACE_SPARKLE,
        FaceName::LookUp => &FACE_LOOK_UP,
        FaceName::Hmm => &FACE_HMM,
        FaceName::Peek => &FACE_PEEK,
        FaceName::Flat => &FACE_FLAT,
    }
}

/// Whether a blink scale may apply. `false` copies the TypeScript face `noBlink` flag.
pub fn face_blinks(face: FaceName) -> bool {
    match face {
        FaceName::Neutral => true,
        FaceName::Dots => true,
        FaceName::Wide => true,
        FaceName::Tiny => true,
        FaceName::Lines => false,
        FaceName::Focus => true,
        FaceName::Worry => true,
        FaceName::Smirk => true,
        FaceName::Happy => false,
        FaceName::Content => false,
        FaceName::Sleepy => false,
        FaceName::Dizzy => false,
        FaceName::Sparkle => false,
        FaceName::LookUp => true,
        FaceName::Hmm => true,
        FaceName::Peek => true,
        FaceName::Flat => true,
    }
}

